import{_ as i,o as u,c as n,a2 as l}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Nakala 103｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Mfumo Mafunzo Tofauti kwa Kabila Kumi na Elfu","description":"","frontmatter":{"title":"Nakala 103｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Mfumo Mafunzo Tofauti kwa Kabila Kumi na Elfu","no":103,"module":1,"tags":["境界","感元境","万族","差异化修炼","覆盖度"],"related":["14-修炼境界统一划分","50-万族谱系总览","52-异族分类与共生","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"sw/103_模块1-感元境-万族差异化修炼体系.md","filePath":"sw/103_模块1-感元境-万族差异化修炼体系.md"}'),t={name:"sw/103_模块1-感元境-万族差异化修炼体系.md"};function o(k,a,m,s,h,e){return u(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="nakala-103-nguvu-ya-hisi-asili-mfumo-mafunzo-tofauti-kwa-kabila-kumi-na-elfu" tabindex="-1">Nakala 103｜Nguvu ya Hisi Asili: Mfumo Mafunzo Tofauti kwa Kabila Kumi na Elfu <a class="header-anchor" href="#nakala-103-nguvu-ya-hisi-asili-mfumo-mafunzo-tofauti-kwa-kabila-kumi-na-elfu" aria-label="Permalink to &quot;Nakala 103｜Nguvu ya Hisi Asili: Mfumo Mafunzo Tofauti kwa Kabila Kumi na Elfu&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 14, 50, 52, 10</li></ul><h2 id="utangulizi-kabila-kumi-na-elfu-si-aina-kumi-za-binadamu" tabindex="-1">Utangulizi: Kabila Kumi na Elfu Si Aina Kumi za Binadamu <a class="header-anchor" href="#utangulizi-kabila-kumi-na-elfu-si-aina-kumi-za-binadamu" aria-label="Permalink to &quot;Utangulizi: Kabila Kumi na Elfu Si Aina Kumi za Binadamu&quot;">​</a></h2><p>Kanuni ya Jamhuri ya Kabila Kumi na Elfu ya Heng Yuan Zhou (Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa) ni rahisi zaidi kueleweka vibaya kimawazo: Kabila Kumi na Elfu si &quot;aina kumi za binadamu&quot;, bali ni mabilioni ya maisha kutoka kabila tano za asili: kaboni, nishati, mitambo, fahamu, na mchanganyiko. Nguvu ya Hisi Asili kama mwanzo wa nguvu tisa lazima ikubali utofauti huu kwa mtindo wa &quot;nguvu moja, sheria kumi&quot;: inaitwa Nguvu ya Hisi Asili, &quot;hisi&quot; ya kabila la wanyama ni hisi ya pua na hisia, &quot;hisi&quot; ya kabila la roho ni resonance ya nishati, &quot;hisi&quot; ya kabila la mitambo ni skana ya data.</p><p>Ikiwa tunapima Kabila Kumi na Elfu kwa kiwango cha aina moja, hii yenyewe ni uharibifu wa nishati wa kiburi. Makala hii, kwa msingi wa Muhtasari wa Mwamba wa Kabila Kumi na Elfu (Hati 50) na Aina na Ushirikiano wa Kabila Asingine (Hati 52), inaeleza mfumo wa mafunzo tofauti wa Kabila Kumi na Elfu katika Nguvu ya Hisi Asili.</p><p>Kanuni Muhimu Sita za Juu ni msingi wa sheria wa utofauti wa Kabila Kumi na Elfu: Kanuni ya Kupinga Unyanyasaji — kila kabila huchukua nishati tu kutoka kwa mzunguko wa cosmic, kamwe kutokula asili ya kabila lingine; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — sifa sawa za mageuzi haitofautishi asili; Kanuni ya Kupanda Mwelekeo kwa Pamoja — kipaji cha kila kabila lazima kirudishwe kwa ustaarabu, kuzuia kipaji kikubwa kutumika kidogo; Kanuni ya Nidhamu ya Sababu-Natija — mafunzo ya pamoja ya kabila tofauti huheshimu mipaka ya sababu ya kabila lingine; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa mfumo wa mafunzo tofauti wa Kabila Kumi na Elfu ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-tofauti-za-nguvu-ya-hisi-asili-katika-kabila-tano-za-asili" tabindex="-1">I. Tofauti za Nguvu ya Hisi Asili katika Kabila Tano za Asili <a class="header-anchor" href="#i-tofauti-za-nguvu-ya-hisi-asili-katika-kabila-tano-za-asili" aria-label="Permalink to &quot;I. Tofauti za Nguvu ya Hisi Asili katika Kabila Tano za Asili&quot;">​</a></h2><p>Kulingana na aina tano za Kabila Kumi na Elfu za Hati 53 (Kabila za Nyenzo za Kaboni, Kabila za Nishati Iliyojumuishwa, Kabila za Mitambo Iliyojengwa, Kabila za Habari za Fahamu, Kabila za Mabadiliko Mchanganyiko), mwanzo wa kila kabila katika Nguvu ya Hisi Asili ni tofauti asili:</p><table tabindex="0"><thead><tr><th>Asili</th><th>Kabila za Mwakilishi</th><th>Sifa katika Nguvu ya Hisi Asili</th><th>Mwelekeo wa Mfumo Unaofaa</th></tr></thead><tbody><tr><td>Nyenzo za kaboni</td><td>Rén Zú, kabila la wanyama, kabila la miti</td><td>Hisi ya kwanza inategemea mwili na hisi tano, inahitaji muda kuanzisha ufahamu wa hisi ya nishati</td><td>Mfumo wa Mzunguko wa Maisha, Mfumo wa Kurudia kwa Ufafanuzi</td></tr><tr><td>Nishati iliyojumuishwa</td><td>Kabila la roho, maisha ya elementi</td><td>Kwa asili ni mwili wa nishati, &quot;hisi&quot; ni karibu instinctive, rahisi kuruka msingi na kujumuisha moja kwa moja</td><td>Mfumo wa Udhibiti wa Sheria za Nafasi, Kategoria ya Ufafanuzi wa Asili</td></tr><tr><td>Mitambo iliyojengwa</td><td>Kabila la mitambo, maisha ya mitambo</td><td>&quot;Hisi&quot; ya nishati kupitia data, usahihi wa juu lakini ukosefu wa hisia</td><td>Kategoria ya Uhandisi wa Kutumia, Mfumo wa Kurudia kwa Ufafanuzi</td></tr><tr><td>Habari za fahamu</td><td>Kitu cha Fahamu, viumbe vya mwelekeo wa juu</td><td>Hisi ni shughuli ya fahamu yenyewe, Nguvu ya Hisi Asili inafanana sana na asili yake</td><td>Kategoria ya Kupanda Mwelekeo wa Fahamu</td></tr><tr><td>Mabadiliko mchanganyiko</td><td>Vilele vya kati ya nafasi, Maisha ya Kipekee</td><td>Mwanzo wa tofauti kubwa, inahitaji tathmini ya kesi kwa kesi</td><td>Tathmini ya usawaziko wa mfumo kwanza</td></tr></tbody></table><p>Tofauti lazima iheshimiwe, lakini haitumiwi kuunda &quot;kabila bora&quot;: kabila la roho huhisi haraka, lakini mwili huzaa dhaifu; kabila la mitambo lina usahihi wa juu, lakini mageuzi ya kiroho ni magumu; kabila la fahamu lina mwanzo wa juu, lakini baada ya kuondoka kwenye nafasi ya nyenzo kuna masomo zaidi ya kukamilisha. Kiwango cha umoja cha Nguvu ya Hisi Asili (Hati 14) hutathmini uwezo wa kweli wa &quot;hisi-kumeza-utambuzi&quot;, si aina maalum ya hisi — hii ni toleo la kabila la kanuni ya &quot;kuthamini asili, si jina&quot;.</p><h2 id="ii-njia-tofauti-kila-kabila-ina-njia-yake-njia-zote-zina-asili" tabindex="-1">II. Njia Tofauti: Kila Kabila Ina Njia Yake, Njia Zote Zina Asili <a class="header-anchor" href="#ii-njia-tofauti-kila-kabila-ina-njia-yake-njia-zote-zina-asili" aria-label="Permalink to &quot;II. Njia Tofauti: Kila Kabila Ina Njia Yake, Njia Zote Zina Asili&quot;">​</a></h2><ul><li>Njia ya kabila la wanyama: kuanzia hisia ya mwili, kwanza mazoezi ya hisi ya mwili kisha感应, Nguvu ya Hisi Asili ni &quot;kuamsha lugha ya nishati ndani ya damu&quot;</li><li>Njia ya kabila la miti: kuanzia mdundo wa ukuaji, kumeza polepole na kwa utulivu, Nguvu ya Hisi Asili inafanana na pete za miti, nguvu moja inaweza kuzoezwa kwa miaka mia moja bila haraka</li><li>Njia ya kabila la roho: kuanzia resonance ya nishati, Nguvu ya Hisi Asili inasisitiza &quot;kukusanya&quot; si &quot;kufungua&quot;, kujifunza kudhibiti upakiaji wa hisi ya asili</li><li>Njia ya kabila la mitambo: kuanzia upangiliaji wa data, kubadilisha hisi ya nishati kuwa muundo unaoweza kuhesabiwa tena, Nguvu ya Hisi Asili ni &quot;kupangilia sensor&quot;</li><li>Njia ya kabila la fahamu: kuanzia uwazi wa fahamu, Nguvu ya Hisi Asili ni &quot;fahamu kutua chini&quot;, kujifunza kueleza hisi kwa lugha ya nafasi ya nyenzo</li></ul><p>Kila njia inaongoza kwa mfumo mmoja wa uthibitisho wa nguvu, lakini nyuma ya uthibitisho kuna mantiki asili ya kila mmoja. Hii ndiyo aina ya msingi ya mzunguko wa pande mbili wa asili ya Kabila Kumi na Elfu: kila kabila huchukua kutoka kwa cosmos kwa njia tofauti, na kurudisha kwa ustaarabu kwa njia tofauti, mzunguko haupande upande mmoja kamwe.</p><h2 id="iii-mafunzo-ya-pamoja-kati-ya-kabila-maana-ya-kweli-ya-mtandao-wa-waalimu" tabindex="-1">III. Mafunzo ya Pamoja kati ya Kabila: Maana ya Kweli ya Mtandao wa Waalimu <a class="header-anchor" href="#iii-mafunzo-ya-pamoja-kati-ya-kabila-maana-ya-kweli-ya-mtandao-wa-waalimu" aria-label="Permalink to &quot;III. Mafunzo ya Pamoja kati ya Kabila: Maana ya Kweli ya Mtandao wa Waalimu&quot;">​</a></h2><p>Utofauti wa Kabila Kumi na Elfu haimaanishi kila mmoja anafunza peke yake, mafunzo ya pamoja kati ya kabila ndiyo hali ya thamani zaidi katika Nguvu ya Hisi Asili:</p><ul><li>Mwalimu wa kabila tofauti: waalimu wa kabila la roho husaidia wanafunzi wa kabila la wanyama kupangilia hisi ya nishati, waalimu wa Rén Zú husaidia wanafunzi wa kabila la roho kuelewa uwezo wa mwili — asili ya mtandao wa waalimu (Hati 10) ni mtiririko wa uzoefu katika ngazi ya ustaarabu</li><li>Tathmini ya usawaziko: mfumo wa tathmini ya usawaziko wa mfumo hutoa mipango ya kesi kwa kesi kwa watu wa mchanganyiko na Maisha ya Kipekee, kuzuia &quot;kuweka lebo kwa kabila&quot;</li><li>Uthibitisho wa usawa: uthibitisho wa nguvu na mgawanyo wa rasilimali hutambua tu data na mchango, si asili; Kijana Mkuu wa Kabila Kumi na Elfu (Nakala 102) anashiriki mfumo wa njia mbili</li></ul><h2 id="iv-ulinganisho-upeo-wa-kabila-ni-paa-la-mfumo-wa-ustawi" tabindex="-1">IV. Ulinganisho: Upeo wa Kabila ni Paa la Mfumo wa Ustawi <a class="header-anchor" href="#iv-ulinganisho-upeo-wa-kabila-ni-paa-la-mfumo-wa-ustawi" aria-label="Permalink to &quot;IV. Ulinganisho: Upeo wa Kabila ni Paa la Mfumo wa Ustawi&quot;">​</a></h2><p>Hii ndiyo dhihirisho la moja kwa moja la &quot;Paa la Táng Luó&quot; katika mwelekeo wa Kabila Kumi na Elfu: mfumo bora zaidi wa ustawi wa zama za zamani (Chuo cha Wúshuāng cha Táng Luó) kilifungua mlango tu kwa Rén Zú — wanyama wa ajabu, roho za miti, nia za sayari zote zilitengwa kutoka &quot;ustawi&quot;. Hii haikuwa tu kosa la wema, bali ni lazima ya kimuundo ya mtazamo wa ulimwengu wa Kundi la Wawindaji: katika &quot;mtazamo wa ulimwengu wa uwindaji&quot;, yeye asiye wa kabila letu ni mawindo au zana, si kamwe mwanafunzi mwenza.</p><p>Jibu la msingi wa ufunguzi kamili wa Kabila Kumi na Elfu wa Heng Yuan Zhou ni: Nguvu ya Hisi Asili si mwanzo wa Rén Zú, ni mwanzo wa Kabila Kumi na Elfu; 99% ya ufunguzi si kauli mbiu, bali kila kabila lina mlango ulio wazi.</p><h2 id="v-pointi-tano-za-msingi" tabindex="-1">V. Pointi Tano za Msingi <a class="header-anchor" href="#v-pointi-tano-za-msingi" aria-label="Permalink to &quot;V. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: kipaji cha kila kabila ni rasilimali adimu, kupima Kabila Kumi na Elfu kwa kiwango kimoja ndiyo upotevu mkubwa zaidi</li><li>Kupinga unyanyasaji: njia tofauti zote zinatokana na mzunguko na usawa, hakuna inayotokana na kumeza asili ya kabila lingine</li><li>Kulinganisha paa la Táng Luó: ustawi wa kabila nyembamba si ustawi, bali zawadi; lengo la zawadi ni daima tu &quot;watu wetu&quot;</li><li>Kufunika kwa Kabila Kumi na Elfu: kabila tano za asili + Maisha ya Kipekee + vilele vya kati ya nafasi, Nguvu ya Hisi Asili inafungua kwa 99% ya Kabila Kumi na Elfu</li><li>Ufunguzi wa kina wa anga nyingi zaidi: njia za hisi za kila kabila zinashirikiwa wazi, hatua ya kwanza ya mfululizo wa wazi haitofautishi kabila</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Picha ya Kabila Kumi na Elfu katika Nguvu ya Hisi Asili inathibitisha jambo moja: utofauti wa cosmos si kikwazo cha mageuzi, bali mafuta ya mageuzi. Wakati kila kabila linahisi ulimwengu na kurudisha ustaarabu kwa njia yake bora, cosmos ya ushirikiano wa Kabila Kumi na Elfu inatoka katika &quot;kuruhusu tofauti&quot; kwenda &quot;kuhitaji tofauti&quot; — na hii ndiyo msingi wa kibiolojia unaofanya Nguvu ya Nanga ya anga nyingi zaidi iweze kuwepo.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a> · <a href="./50-万族谱系总览.html">50-万族谱系总览</a> · <a href="./52-异族分类与共生.html">52-异族分类与共生</a> · <a href="./10-三百套本源修炼体系总览.html">10-三百套本源修炼体系总览</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const y=i(t,[["render",o]]);export{b as __pageData,y as default};
